  /* At end of Tx process, restore huart->gState to Ready */
  huart->gState = HAL_UART_STATE_READY;
}"}, {"function_name": "UART_DMATransmitCplt", "function_type": "IRQ", "functionality": "DMA UART transmit process complete callback that handles DMA transmission completion, manages interrupt states, and triggers appropriate completion callbacks", "classification_reason": "This function is called from DMA interrupt handler (HAL_DMA_IRQHandler) and performs interrupt-related operations including enabling UART Transmit Complete Interrupt (USART_CR1_TCIE) and disabling DMA transfer request (USART_CR3_DMAT). It manages hardware interrupt states and serves as a callback for DMA completion events.", "has_replacement": true, "function_replacement": "static void UART_DMATransmitCplt(DMA_HandleTypeDef *hdma)
{
  UART_HandleTypeDef *huart = (UART_HandleTypeDef *)(hdma->Parent);

  /* DMA Normal mode */
  if (hdma->Init.Mode != DMA_CIRCULAR)
  {
    huart->TxXferCount = 0U;

    /* Skip DMA disable operation for transmit request */
    /* Original: ATOMIC_CLEAR_BIT(huart->Instance->CR3, USART_CR3_DMAT); */

    /* Skip UART Transmit Complete Interrupt enable */
    /* Original: ATOMIC_SET_BIT(huart->Instance->CR1, USART_CR1_TCIE); */
  }
  /* DMA Circular mode */
  else
  {
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
    /*Call registered Tx complete callback*/
    huart->TxCpltCallback(huart);
#else
    /*Call legacy weak Tx complete callback*/
    HAL_UART_TxCpltCallback(huart);
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */
  }
}"}], "replacement_updates": [{"function_name": "UART_Receive_IT", "replacement_code": "/**
* @brief  Receives an amount of data in non blocking mode
* @param  huart  Pointer to a UART_HandleTypeDef structure that contains
*                the configuration information for the specified UART module.
* @retval HAL status
*/
static HAL_StatusTypeDef UART_Receive_IT(UART_HandleTypeDef *huart)
{
  /* Check that a Rx process is ongoing */
  if (huart->RxState == HAL_UART_STATE_BUSY_RX)
  {
    /* In emulation, simulate receiving one byte at a time from stdin */
    uint8_t received_byte;
    int bytes_read = HAL_BE_In(&received_byte, 1);

    if (bytes_read > 0)
    {
      /* Store the received byte */
      *huart->pRxBuffPtr = received_byte;
      huart->pRxBuffPtr += 1U;

      if (--huart->RxXferCount == 0U)
      {
        /* Rx process is completed, restore huart->RxState to Ready */
        huart->RxState = HAL_UART_STATE_READY;

        /* Initialize type of RxEvent to Transfer Complete */
        huart->RxEventType = HAL_UART_RXEVENT_TC;

        /* Check current reception Mode :
           If Reception till IDLE event has been selected : */
        if (huart->ReceptionType == HAL_UART_RECEPTION_TOIDLE)
        {
          /* Set reception type to Standard */
          huart->ReceptionType = HAL_UART_RECEPTION_STANDARD;

#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
          /*Call registered Rx Event callback*/
          huart->RxEventCallback(huart, huart->RxXferSize);
#else
          /*Call legacy weak Rx Event callback*/
          HAL_UARTEx_RxEventCallback(huart, huart->RxXferSize);
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */
        }
        else
        {
          /* Standard reception API called */
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
          /*Call registered Rx complete callback*/
          huart->RxCpltCallback(huart);
#else
          /*Call legacy weak Rx complete callback*/
          HAL_UART_RxCpltCallback(huart);
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */
        }

        return HAL_OK;
      }
      return HAL_OK;
    }
    else
    {
      /* No data available yet */
      return HAL_OK;
    }
  }
  else
  {
    return HAL_BUSY;
  }
}", "reason": "Replaced hardware register access (huart->Instance->DR) with emulated data reception using HAL_BE_In. The function was reading from non-existent hardware data register in emulation environment. Now it simulates receiving data from stdin while preserving the state machine and callback logic."}, {"function_name": "UART_WaitOnFlagUntilTimeout", "replacement_code": "/**
* @brief  This function handles UART Communication Timeout. It waits
*         until a flag is no longer in the specified status.
* @param  huart  Pointer to a UART_HandleTypeDef structure that contains
*                the configuration information for the specified UART module.
* @param  Flag specifies the UART flag to check.
* @param  Status The actual Flag status (SET or RESET).
* @param  Tickstart Tick start value
* @param  Timeout Timeout duration
* @retval HAL status
*/
static HAL_StatusTypeDef UART_WaitOnFlagUntilTimeout(UART_HandleTypeDef *huart, uint32_t Flag, FlagStatus Status,
                                                     uint32_t Tickstart, uint32_t Timeout)
{
  /* In emulation, we don't wait for hardware flags */
  /* Check for timeout immediately */
  if (Timeout != HAL_MAX_DELAY)
  {
    if (((HAL_GetTick() - Tickstart) > Timeout) || (Timeout == 0U))
    {
      return HAL_TIMEOUT;
    }
  }

  /* For RXNE flag (receive data ready), simulate data availability */
  if (Flag == UART_FLAG_RXNE && Status == RESET)
  {
    /* In emulation, we assume data is always ready */
    return HAL_OK;
  }

  /* For TXE flag (transmit data empty), simulate ready to transmit */
  if (Flag == UART_FLAG_TXE && Status == RESET)
  {
    /* In emulation, we assume transmitter is always ready */
    return HAL_OK;
  }

  /* For TC flag (transmit complete), simulate completion */
  if (Flag == UART_FLAG_TC && Status == RESET)
  {
    /* In emulation, we assume transmission is always complete */
    return HAL_OK;
  }

  /* Default: return OK to avoid blocking */
  return HAL_OK;
}", "reason": "Fixed potential infinite loop in UART_WaitOnFlagUntilTimeout by removing hardware flag checking. The original function had a while loop waiting for hardware flags that don't exist in emulation, which could cause infinite loops. The replacement returns appropriate status based on the flag being checked without blocking on hardware."}, {"function_name": "HAL_UART_IRQHandler", "replacement_code": "/**
* @brief  This function handles UART interrupt request.
* @param  huart  Pointer to a UART_HandleTypeDef structure that contains
*                the configuration information for the specified UART module.
* @retval None
*/
void HAL_UART_IRQHandler(UART_HandleTypeDef *huart)
{
  /* In emulation environment, simulate UART interrupt handling */

  /* Check if we're in receive mode and should receive data */
  if (huart->RxState == HAL_UART_STATE_BUSY_RX)
  {
    /* Simulate receiving data from stdin */
    int bytes_read = HAL_BE_In(huart->pRxBuffPtr, huart->RxXferCount);

    if (bytes_read > 0)
    {
      /* Update buffer pointer and count */
      huart->pRxBuffPtr += bytes_read;
      huart->RxXferCount -= bytes_read;

      /* If all data received, complete the transfer */
      if (huart->RxXferCount == 0U)
      {
        huart->RxState = HAL_UART_STATE_READY;
        huart->RxEventType = HAL_UART_RXEVENT_TC;

        /* Call appropriate callback */
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
        if (huart->ReceptionType == HAL_UART_RECEPTION_TOIDLE)
        {
          huart->RxEventCallback(huart, huart->RxXferSize);
        }
        else
        {
          huart->RxCpltCallback(huart);
        }
#else
        if (huart->ReceptionType == HAL_UART_RECEPTION_TOIDLE)
        {
          HAL_UARTEx_RxEventCallback(huart, huart->RxXferSize);
        }
        else
        {
          HAL_UART_RxCpltCallback(huart);
        }
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */
      }
    }
    return;
  }

  /* Check if we're in transmit mode */
  if (huart->TxState == HAL_UART_STATE_BUSY_TX)
  {
    /* Transmit complete - update state */
    huart->TxState = HAL_UART_STATE_READY;

    /* Call transmit complete callback */
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
    huart->TxCpltCallback(huart);
#else
    HAL_UART_TxCpltCallback(huart);
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */

    return;
  }

  /* Handle error conditions if needed */
  if (huart->ErrorCode != HAL_UART_ERROR_NONE)
  {
    /* Call error callback */
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
    huart->ErrorCallback(huart);
#else
    HAL_UART_ErrorCallback(huart);
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */

    huart->ErrorCode = HAL_UART_ERROR_NONE;
    return;
  }
}", "reason": "Fixed exceptional loop in HAL_UART_IRQHandler by replacing hardware register reads with emulated behavior. The function was trying to read non-existent hardware registers (huart->Instance->SR, CR1, CR3) in the emulation environment, causing an infinite loop. The replacement preserves the interrupt handling logic while using HAL_BE_In for data reception simulation and maintaining proper state machine transitions."}, {"function_name": "HAL_UARTEx_ReceiveToIdle_DMA", "replacement_code": "HAL_StatusTypeDef HAL_UARTEx_ReceiveToIdle_DMA(UART_HandleTypeDef *huart, uint8_t *pData, uint16_t Size)
{
    // Replace UART DMA reception with HAL_BE_In for data input
    // The idle detection functionality is not preserved in this replacement
    int result = HAL_BE_In(pData, Size);
    if (result >= 0)
    {
        return HAL_OK;
    }
    else
    {
        return HAL_ERROR;
    }
}", "reason": "Fixed return type from 'int' to 'HAL_StatusTypeDef' to match the original declaration"}, {"function_name": "HAL_UARTEx_ReceiveToIdle_IT", "replacement_code": "HAL_StatusTypeDef HAL_UARTEx_ReceiveToIdle_IT(UART_HandleTypeDef *huart, uint8_t *pData, uint16_t Size)
{
  HAL_StatusTypeDef status;

  /* Check that a Rx process is not already ongoing */
  if (huart->RxState == HAL_UART_STATE_READY)
  {
    if ((pData == NULL) || (Size == 0U))
    {
      return HAL_ERROR;
    }

    /* Set Reception type to reception till IDLE Event*/
    huart->ReceptionType = HAL_UART_RECEPTION_TOIDLE;
    huart->RxEventType = HAL_UART_RXEVENT_TC;

    /* Skip the call to UART_Start_Receive_IT as it may have hardware dependencies */
    /* Instead, set up the receive state directly */
    huart->pRxBuffPtr = pData;
    huart->RxXferSize = Size;
    huart->RxXferCount = Size;
    huart->ErrorCode = HAL_UART_ERROR_NONE;
    huart->RxState = HAL_UART_STATE_BUSY_RX;

    status = HAL_OK;

    /* Check Rx process has been successfully started */
    if (status == HAL_OK)
    {
      if (huart->ReceptionType == HAL_UART_RECEPTION_TOIDLE)
      {
        /* Skip hardware-specific operations */
        /* Original: __HAL_UART_CLEAR_IDLEFLAG(huart); */
        /* Original: ATOMIC_SET_BIT(huart->Instance->CR1, USART_CR1_IDLEIE); */

        /* In emulation, we can simulate receiving data immediately */
        /* Use HAL_BE_In to read data from stdin */
        int received = HAL_BE_In(pData, Size);
        if (received > 0)
        {
          huart->RxXferCount = Size - received;
          if (huart->RxXferCount == 0)
          {
            /* Reception complete */
            huart->RxState = HAL_UART_STATE_READY;

            /* IMPORTANT: We do NOT call HAL_UARTEx_RxEventCallback to avoid loops */
            /* Instead, we call the standard receive complete callback */
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
            if (huart->RxCpltCallback != NULL)
            {
              huart->RxCpltCallback(huart);
            }
#else
            HAL_UART_RxCpltCallback(huart);
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */
          }
        }
        else
        {
          /* Error receiving data */
          status = HAL_ERROR;
          huart->RxState = HAL_UART_STATE_READY;
        }
      }
      else
      {
        /* In case of errors already pending when reception is started,
           Interrupts may have already been raised and lead to reception abortion.
           (Overrun error for instance).
           In such case Reception Type has been reset to HAL_UART_RECEPTION_STANDARD. */
        status = HAL_ERROR;
        huart->RxState = HAL_UART_STATE_READY;
      }
    }

    return status;
  }
  else
  {
    return HAL_BUSY;
  }
}", "reason": "Added replacement for HAL_UARTEx_ReceiveToIdle_IT to fix exceptional loop issue. This function contains MMIO operations (ATOMIC_SET_BIT) and calls UART_Start_Receive_IT. The replacement:
1. Skips the call to UART_Start_Receive_IT which may have hardware dependencies
2. Sets up the receive state directly
3. Skips hardware-specific operations (__HAL_UART_CLEAR_IDLEFLAG and ATOMIC_SET_BIT)
4. Uses HAL_BE_In to read data from stdin in emulation
